INSERT INTO seat_inventory (id, tenant_id, trip_id, seat_number, status)
SELECT 
    gen_random_uuid(),
    t.tenant_id,
    t.id,
    row_num || col,
    CASE 
        WHEN (row_num || col) IN ('1A', '2B', '3C') THEN 'BOOKED'
        ELSE 'AVAILABLE'
    END
FROM trips t
CROSS JOIN generate_series(1, 10) AS row_num
CROSS JOIN (VALUES ('A'), ('B'), ('C'), ('D')) AS cols(col);

