INSERT INTO route_segment_stats (id, tenant_id, route_id, from_stop_id, to_stop_id, historical_avg_seconds, std_dev_seconds, sample_count)
SELECT
    gen_random_uuid(),
    rs1.tenant_id,
    rs1.route_id,
    rs1.stop_id,
    rs2.stop_id,
    240 + (rs1.stop_sequence * 45),
    30,
    150
FROM route_stops rs1
JOIN route_stops rs2 ON rs1.route_id = rs2.route_id AND rs2.stop_sequence = rs1.stop_sequence + 1
ON CONFLICT (route_id, from_stop_id, to_stop_id) DO UPDATE
SET historical_avg_seconds = EXCLUDED.historical_avg_seconds,
    std_dev_seconds = EXCLUDED.std_dev_seconds,
    sample_count = EXCLUDED.sample_count;
